/**
 * Generate command handler
 */
import { INVALID_ARGUMENT } from "../../../src/errors/index.js";
import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { generateCommand } from "./index.js";
import { showHeader } from "../../utils/index.js";
import { createArgParser } from "../../shared/args.js";
import { cwd } from "../../../src/platform/index.js";
import { AUTH_PRESETS, isAuthPreset, SCAFFOLD_TYPES } from "../../scaffold/engine.js";
const VALID_TYPES = [...SCAFFOLD_TYPES, "auth", "integration"];
const getGenerateArgsSchema = defineSchema((v) => v.object({
    type: v.enum(VALID_TYPES).optional(),
    name: v.string().optional(),
}));
const GenerateArgsSchema = lazySchema(getGenerateArgsSchema);
export const parseGenerateArgs = createArgParser(GenerateArgsSchema, {
    type: { keys: ["type"], type: "string", positional: 0 },
    name: { keys: ["name"], type: "string", positional: 1 },
});
export async function handleGenerateCommand(args) {
    showHeader();
    const result = parseGenerateArgs(args);
    if (!result.success) {
        throw INVALID_ARGUMENT.create({
            detail: `Invalid arguments. Usage: veryfront generate <type> <name>\n\nValid types: ${VALID_TYPES.join(", ")}`,
        });
    }
    const { type, name } = result.data;
    // Integration type doesn't require a name (prompts interactively)
    if (type === "integration") {
        await generateCommand(cwd(), type, name ?? "");
        return;
    }
    if (type === "auth" && (!name || !isAuthPreset(name))) {
        throw INVALID_ARGUMENT.create({
            detail: `Invalid arguments. Usage: veryfront generate auth <preset>\n\nValid presets: ${AUTH_PRESETS.join(", ")}`,
        });
    }
    if (!type || !name) {
        throw INVALID_ARGUMENT.create({
            detail: `Invalid arguments. Usage: veryfront generate <type> <name>\n\nValid types: ${VALID_TYPES.join(", ")}`,
        });
    }
    await generateCommand(cwd(), type, name);
}
